package com.soulsync.domain;
import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.UUID; import com.soulsync.domain.Enums.Plan;
@Entity @Table(name="subscriptions") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Subscription { @Id private UUID id; @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false,unique=true) private User user; @Enumerated(EnumType.STRING) @Column(nullable=false) @Builder.Default private Plan plan=Plan.FREE; @Column(name="starts_at") private Instant startsAt; @Column(name="ends_at") private Instant endsAt; @Column(name="provider_customer_id") private String providerCustomerId; @Column(name="provider_subscription_id") private String providerSubscriptionId; @Column(name="updated_at",nullable=false) private Instant updatedAt; @PrePersist void pre(){if(id==null)id=UUID.randomUUID();if(updatedAt==null)updatedAt=Instant.now();} @PreUpdate void up(){updatedAt=Instant.now();} }
